// === ClinDeck Study Bot · Planificador ===
// Lee Exámenes/Mazos/Recordatorios de Notion, calcula días restantes,
// genera tareas (estudiar, crear mazo, día de examen) y arma el resumen diario.

const thresholds = [30, 14, 7, 3, 1]; // días antes del examen que disparan recordatorio

// Nombres de propiedades en TUS bases de Notion. Edítalos si los llamas distinto.
const PROP = {
  examTitle: 'Examen', examDate: 'Fecha', examDaysLeft: 'Días restantes', examSubject: 'Materia',
  deckSubject: 'Materia', deckStatus: 'Estado',
  taskTitle: 'Tarea',
};

const startOfDay = (d) => { const x = new Date(d); x.setHours(0,0,0,0); return x; };
const today = startOfDay(new Date());
const fmt = (d) => startOfDay(d).toISOString().slice(0,10);
const daysBetween = (a, b) => Math.round((startOfDay(a) - startOfDay(b)) / 86400000);

const txt = (prop) => {
  if (!prop) return '';
  if (prop.type === 'title') return (prop.title[0] && prop.title[0].plain_text) || '';
  if (prop.type === 'rich_text') return (prop.rich_text[0] && prop.rich_text[0].plain_text) || '';
  if (prop.type === 'select') return (prop.select && prop.select.name) || '';
  if (prop.type === 'status') return (prop.status && prop.status.name) || '';
  return '';
};
const dateOf = (prop) => (prop && prop.date && prop.date.start) || null;

const exams     = ($('Notion · Exámenes').first().json.results) || [];
const decks     = ($('Notion · Mazos').first().json.results) || [];
const reminders = ($('Notion · Recordatorios').first().json.results) || [];

// Recordatorios ya existentes (dedupe por título)
const existing = new Set(reminders.map(r => txt(r.properties[PROP.taskTitle])));
// Materias que YA tienen un mazo "Listo"
const readySubjects = new Set(
  decks.filter(d => txt(d.properties[PROP.deckStatus]).toLowerCase() === 'listo')
       .map(d => txt(d.properties[PROP.deckSubject]).toLowerCase())
);

const examUpdates = [];
const tasksToCreate = [];

for (const ex of exams) {
  const name = txt(ex.properties[PROP.examTitle]) || 'Examen';
  const subject = txt(ex.properties[PROP.examSubject]) || name;
  const ds = dateOf(ex.properties[PROP.examDate]);
  if (!ds) continue;
  const daysLeft = daysBetween(ds, today);
  if (daysLeft < 0) continue;

  examUpdates.push({ pageId: ex.id, daysLeft, name });

  for (const t of thresholds) {
    if (daysLeft === t) {
      const title = `📕 Estudiar para ${name} (faltan ${t} días)`;
      if (!existing.has(title)) tasksToCreate.push({ title, date: fmt(today), type: 'Estudiar' });
    }
  }
  if (daysLeft <= 14 && !readySubjects.has(subject.toLowerCase())) {
    const title = `🃏 Crear mazo de ${subject} para ${name}`;
    if (!existing.has(title)) tasksToCreate.push({ title, date: fmt(today), type: 'Crear mazo' });
  }
  if (daysLeft === 0) {
    const title = `🚨 HOY: ${name}`;
    if (!existing.has(title)) tasksToCreate.push({ title, date: fmt(today), type: 'Examen' });
  }
}

// Resumen diario (email + Notion)
const upcoming = examUpdates.slice().sort((a,b)=>a.daysLeft-b.daysLeft);
let html = `<h2>📅 Tu agenda ClinDeck — ${fmt(today)}</h2><h3>Próximos exámenes</h3><ul>`;
html += upcoming.length ? upcoming.map(u=>`<li><b>${u.name}</b> — faltan <b>${u.daysLeft}</b> días</li>`).join('') : '<li>Sin exámenes próximos 🎉</li>';
html += '</ul><h3>Tareas creadas hoy</h3><ul>';
html += tasksToCreate.length ? tasksToCreate.map(t=>`<li>${t.title}</li>`).join('') : '<li>Nada nuevo por hoy ✅</li>';
html += '</ul><p style="color:#64748B;font-size:12px">Generado por ClinDeck Study Bot · n8n</p>';

const text = `Agenda ${fmt(today)}\nExámenes:\n` +
  upcoming.map(u=>`- ${u.name}: ${u.daysLeft} días`).join('\n') +
  `\nTareas:\n` + tasksToCreate.map(t=>`- ${t.title}`).join('\n');

return [{ json: { examUpdates, tasksToCreate, digestHtml: html, digestText: text, count: tasksToCreate.length } }];

// Una salida por examen a actualizar
const updates = $input.first().json.examUpdates || [];
return updates.map(u => ({ json: u }));

// Una salida por tarea/recordatorio a crear
const tasks = $input.first().json.tasksToCreate || [];
return tasks.map(t => ({ json: t }));
